    var pats = [
      /\b(?:[Ii] am|[Ii]['’]m|[Ii]t is|[Ii]t['’]s|[Tt]his is|[Mm]y name is)\s+([A-Z][a-z]+(?:\s+[A-Z][a-z]+)?)\b/,
      /\b(?:[Tt]hanks|[Cc]heers|[Rr]egards|[Kk]ind regards|[Tt]hank you)[,!.]?\s+([A-Z][a-z]+(?:\s+[A-Z][a-z]+)?)\b/,
      /(?:^|[.!?]\s+)([A-Z][a-z]+\s+[A-Z][a-z]+),\s+(?:[A-Z][\w&'’-]*\s*){1,4},/
