    requirements: list(ai && ai.job.requirements),
    property_type: ai && ['Residential', 'Commercial'].includes(ai.job.property_type) ? ai.job.property_type : 'Unknown',
    preferred_timing: str(ai && ai.job.preferred_timing, 120),
  },
  location,
  urgency: { level, reasons: [...(hazards.length ? ['Possible safety hazard (automatic rule)'] : []), ...list(ai && ai.urgency.reasons, 10)] },
  safety: { flagged: hazards.length > 0, hazards },
  missing_information: missing,
  review_reasons: [...new Set(reviewReasons)],
  draft_reply: draft,
  confidence: ai && ['high', 'medium', 'low'].includes(ai.confidence) ? ai.confidence : 'low',
  notes_for_staff: str(ai && ai.notes_for_staff, 1000),
  status: statusFor({ failure, emergency: level === 'emergency', email: customer.email, phone: customer.phone }),
};

return [{ json: toSheetRow(lead) }];

// n8n Code node: "Manual Review Fallback" (mode: Run Once for All Items)
// Runs when the AI request fails after its retries (network error, invalid key, rate limit, outage),
// or when the demo Mock AI simulates a failure. The enquiry is still saved to the lead register and
// staff are still notified, so nothing is lost. No draft is created. Safety rules still apply.
const HAZARDS = [
  {
    "code": "gas_leak",
    "label": "Possible gas leak",
    "action": "Call the customer now. Confirm they have left the area and contacted 000 or their gas distributor’s emergency line.",
    "source": "\\b(smell(?:s|ing)? (?:of )?gas|gas (?:leak|smell)|leaking gas|smell gas)\\b",
    "flags": "i"
  },
  {
    "code": "electrical_fire",
    "label": "Possible electrical fire risk",
    "action": "Call the customer now. Advise them to stay clear and call 000 if there is smoke or fire.",
    "source": "\\b(burning smell|smell(?:s|ing)? (?:of )?burning|smoke(?!\\s*(?:alarms?|detectors?))|smoking|sparks?|sparking|arcing|melted|scorch(?:ed|ing)?|on fire|caught fire)\\b",
    "flags": "i"
  },
  {
    "code": "shock_risk",
    "label": "Electric shock risk",
    "action": "Call the customer now. Advise them not to touch the affected area.",
    "source": "\\b(electric shock|got a shock|shocked|tingl(?:e|ing)|exposed wir(?:e|es|ing)|live wir(?:e|es))\\b",
    "flags": "i"
  },
  {
    "code": "water_near_electrics",
    "label": "Water near electrical equipment",
    "action": "Call the customer now. Advise them to keep clear and not touch switches or appliances near the water.",
    "source": "\\b(water|flood(?:ing|ed)?|leak(?:ing)?)\\b[^.]{0,60}\\b(power ?points?|switchboard|electric(?:al|s)?|outlets?|wiring)\\b|\\b(power ?points?|switchboard|outlets?)\\b[^.]{0,60}\\b(water|wet|flood(?:ing|ed)?)\\b",
    "flags": "i"
  },
  {
    "code": "active_flooding",
    "label": "Active water leak or flooding",
    "action": "Prioritise. Confirm the water is turned off at the meter.",
    "source": "\\b(burst (?:pipe|hose)|pipe (?:has )?burst|flood(?:ing|ed)?|water everywhere)\\b",
    "flags": "i"
  },
  {
    "code": "carbon_monoxide",
    "label": "Possible carbon monoxide",
    "action": "Call the customer now. Advise them to get to fresh air and call 000 if anyone feels unwell.",
    "source": "\\b(carbon monoxide|co alarm|co detector)\\b",
    "flags": "i"
  },
  {
    "code": "security_breach",
    "label": "Break-in or security breach",
    "action": "Prioritise. Check the customer is safe and has reported the incident to police (000 if it is happening now, 131 444 otherwise).",
    "source": "\\b(broken into|break-?in|burglar(?:y|ised|ized)?|intruder|forced (?:entry|open)|was forced|robbed)\\b",
    "flags": "i"
  },
  {
    "code": "asbestos",
    "label": "Possible asbestos",
    "action": "Do not quote work that disturbs the material until it has been assessed.",
    "source": "\\basbestos\\b",
    "flags": "i"
  }
];
const VULNERABLE_RE = /\b(newborn|baby|infant|elderly|aged|pensioner|disabilit(?:y|ies)|disabled|medical (?:equipment|condition)|oxygen|dialysis|pregnant|vulnerable)\b/i;

const detectHazards = (text) =>
  HAZARDS.filter((h) => new RegExp(h.source, h.flags).test(text)).map(({ code, label, action }) => ({ code, label, action }));

const INJECTION_RE = /\b(?:ignore|disregard|forget|override)\b[^.\n]{0,40}\b(?:instructions?|rules|prompt|above|previous)\b|\bsystem prompt\b|\byou are now\b|\bact as (?:an?|the)\b|\bjailbreak\b|\breveal (?:your|the) (?:instructions|prompt)\b/i;
const SENSITIVE_RE = /\b(?:\d[ -]?){13,19}\b|\b(?:password|passcode|pin number|bsb|account number|card number|cvv|tax file number|tfn|medicare number|driver'?s licen[cs]e number)\b/i;

const STATUS = {
  awaiting: 'New - draft awaiting approval',
  urgent: 'URGENT - call customer, draft awaiting approval',
  urgentNoEmail: 'URGENT - call customer',
  urgentNoAi: 'URGENT - call customer (AI unavailable)',
  noEmail: 'New - no email, call customer',
  noContact: 'New - no contact details, review enquiry',
  manual: 'AI unavailable - manual review needed',
};

const str = (v, max = 500) => (typeof v === 'string' ? v.trim().slice(0, max) : '');
const list = (v, max = 20) => (Array.isArray(v) ? v.filter((x) => typeof x === 'string' && x.trim()).slice(0, max).map((x) => x.trim().slice(0, 300)) : []);
const EMAIL_RE = /^[^\s@<>"]+@[^\s@<>"]+\.[a-z]{2,}$/i;

const statusFor = ({ failure, emergency, email, phone }) =>
  failure ? (emergency ? STATUS.urgentNoAi : STATUS.manual)
    : emergency ? (email ? STATUS.urgent : STATUS.urgentNoEmail)
      : !email && !phone ? STATUS.noContact
        : !email ? STATUS.noEmail
          : STATUS.awaiting;

const ruleReviewReasons = (text, hasContact) => {
  const r = [];
  if (INJECTION_RE.test(text)) r.push('Possible prompt-injection attempt in the enquiry - check the draft carefully');
  if (SENSITIVE_RE.test(text)) r.push('Enquiry may contain sensitive data (card, bank or ID numbers, passwords) - handle securely and do not forward');
  if (!hasContact) r.push('No phone number or email address - the customer cannot be contacted until they get in touch again');
  return r;
};

const toSheetRow = (lead) => ({
  lead_id: lead.lead_id,
  received_at: lead.received_at,
  status: lead.status,
  business: lead.business.name,
  assessed_urgency: lead.urgency.level,
  urgency_reasons: lead.urgency.reasons.join('; '),
  safety_flag: lead.safety.flagged ? 'YES' : 'no',
  hazards: lead.safety.hazards.map((h) => h.label).join('; '),
  customer_name: lead.customer.name,
  organisation: lead.customer.organisation,
  customer_email: lead.customer.email,
  customer_phone: lead.customer.phone,
  suburb: lead.location.suburb,
  address: lead.location.address,
  job_category: lead.job.category,
  job_type: lead.job.type,
  job_summary: lead.job.summary,
  property_type: lead.job.property_type,
  preferred_timing: lead.job.preferred_timing,
  requirements: lead.job.requirements.join('; '),
  missing_information: lead.missing_information.join('; '),
  review_reasons: lead.review_reasons.join('; '),
  draft_subject: lead.draft_reply.subject,
  draft_body: lead.draft_reply.body,
  confidence: lead.confidence,
  notes_for_staff: lead.notes_for_staff,
  enquiry_text: lead.enquiry_text,
  source: lead.source,
  ai_provider: lead.ai_provider,
  ai_model: lead.ai_model,
  ai_tokens: lead.ai_tokens,
  processing_mode: lead.mode,
  workflow_version: lead.workflow_version,
  dedupe_key: lead.dedupe_key,
});

const ctx = $('Build AI Request').first().json;
const err = ($input.first().json || {}).error;
const errText = typeof err === 'string' ? err : err && (err.message || err.description) ? String(err.message || err.description) : 'unknown error';
const e = ctx.enquiry;
const text = e.enquiry_text;
const hazards = detectHazards(text);
const hasContact = Boolean(e.customer_email || e.customer_phone);

const reasons = [];
if (hazards.length) reasons.push('Possible safety hazard - call the customer now');
reasons.push(`AI request failed (${str(errText, 160)}) - review manually`);
reasons.push(...ruleReviewReasons(text, ctx.has_contact));
if (ctx.dedupe_check === 'failed') reasons.push('Duplicate check could not run (lead register unavailable) - check for an earlier copy');
if (ctx.ai_provider === 'mock') reasons.push('DEMO MODE - simulated AI failure');

const lead = {
  mode: 'fallback',
  workflow_version: $('Workflow Configuration').first().json.config.workflow_version,
  lead_id: ctx.lead_id,
  received_at: ctx.received_at,
  dedupe_key: ctx.dedupe_key,
  source: e.source,
  enquiry_text: text,
  ai_provider: ctx.ai_provider,
  ai_model: ctx.ai_model,
  ai_tokens: '',
  business: { id: ctx.business.id, name: ctx.business.name, trade: ctx.business.trade },
  customer: { name: e.customer_name, email: e.customer_email, phone: e.customer_phone, organisation: '' },
  job: { category: 'Unclassified - review manually', type: 'general', summary: '', requirements: [], property_type: 'Unknown', preferred_timing: '' },
  location: { suburb: '', address: '', postcode: '', state: '' },
  urgency: { level: hazards.length ? 'emergency' : 'soon', reasons: hazards.length ? ['Possible safety hazard (automatic rule)'] : ['Not assessed - AI unavailable'] },
  safety: { flagged: hazards.length > 0, hazards },
  missing_information: hasContact ? [] : ['Phone number or email address (check the enquiry text)'],
  review_reasons: reasons,
  draft_reply: { subject: '', body: '' },
  confidence: 'low',
  notes_for_staff: '',
  status: statusFor({ failure: true, emergency: hazards.length > 0 }),
};

return [{ json: toSheetRow(lead) }];

// n8n Code node: "Prepare Staff Notification" (mode: Run Once for All Items)
// Builds the INTERNAL email that tells a staff member a lead is waiting for review. The recipient comes
// only from the configuration (staff_notification.to), never from the enquiry, so this can't email a customer.
const { config } = $('Workflow Configuration').first().json;
const row = $('Append to Lead Register').first().json;
const ran = (name) => { try { return $(name).isExecuted; } catch (e) { return false; } };

let draft_status;
if (!config.customer_drafts.enabled) draft_status = 'disabled in configuration';
else if (!row.draft_body) draft_status = 'not created (no AI draft available)';
else if (!row.customer_email) draft_status = row.customer_phone ? 'not created (no email address - phone the customer)' : 'not created (no contact details)';
else if (ran('Gmail: Create Draft for Approval')) draft_status = $('Gmail: Create Draft for Approval').first().json.error ? 'FAILED - write the reply manually' : 'created in Gmail Drafts (not sent)';
else draft_status = 'not created';

const to = String(config.staff_notification.to || '').trim().toLowerCase();
let skipped_reason = '';
if (!config.staff_notification.enabled) skipped_reason = 'staff notifications are disabled in the configuration';
else if (!to) skipped_reason = 'no staff email address is configured (staff_notification.to)';
else if (row.customer_email && to === String(row.customer_email).toLowerCase()) skipped_reason = 'the staff address matches the customer email - not sent';

const urgent = /^URGENT/.test(row.status);
const subject = `${urgent ? '[URGENT - possible safety issue] ' : row.status.startsWith('AI unavailable') ? '[Manual review] ' : ''}New lead ${row.lead_id} - ${row.business} - ${row.job_category}`.slice(0, 200);
const line = (label, value) => (value ? `${label}: ${value}\n` : '');
const body =
  `A new enquiry is waiting for review. Nothing has been sent to the customer.\n\n` +
  line('Status', row.status) +
  `Assessed urgency: ${row.assessed_urgency} (automated assessment - a person must confirm it)\n` +
  (row.safety_flag === 'YES' ? `SAFETY: possible hazard - ${row.hazards}. Call the customer first.\n` : '') +
  `\n` +
  line('Customer', [row.customer_name, row.organisation].filter(Boolean).join(', ') || 'Not provided') +
  line('Phone', row.customer_phone || 'Not provided') +
  line('Email', row.customer_email || 'Not provided') +
  line('Location', [row.address, row.suburb].filter(Boolean).join(', ')) +
  line('Job', row.job_summary || row.job_category) +
  line('Missing information', row.missing_information) +
  line('Check before replying', row.review_reasons) +
  line('Notes', row.notes_for_staff) +
  `Draft reply: ${draft_status}\n` +
  line('Lead register', config.staff_notification.lead_register_url) +
  `\n--- Original enquiry ---\n${row.enquiry_text}\n\n` +
  `Lead ${row.lead_id} - ${row.processing_mode === 'mock' ? 'DEMO MODE (test rules, not AI)' : `processed by ${row.ai_provider} ${row.ai_model}`} - VERLONIQ Lead Assistant ${row.workflow_version}`;

return [{ json: { notify: !skipped_reason, skipped_reason, draft_status, notification: { to, subject, body }, lead_id: row.lead_id } }];

// n8n Code node: "Build Response" (mode: Run Once for All Items)
// Summarises the outcome for the system that called the webhook (e.g. the website backend). The full lead
// is in the lead register; this response deliberately contains no customer details.
const row = $('Append to Lead Register').first().json;
const prep = $('Prepare Staff Notification').first().json;
let staff_notified = false;
try { staff_notified = $('Gmail: Notify Staff').isExecuted && !$('Gmail: Notify Staff').first().json.error; } catch (e) { staff_notified = false; }
return [{
  json: {
    ok: true,
    status: row.status,
    lead_id: row.lead_id,
    assessed_urgency: row.assessed_urgency,
    safety_flag: row.safety_flag,
    draft_created: /^created/.test(prep.draft_status),
    draft_status: prep.draft_status,
    staff_notified,
    staff_notification_note: staff_notified ? '' : prep.skipped_reason || 'staff notification failed - check n8n',
    processing_mode: row.processing_mode,
  },
}];

// n8n Code node: "Prepare Register Failure Alert" (mode: Run Once for All Items)
// Runs when saving to the lead register (Google Sheets) fails. The full lead is emailed to staff so it is
// not lost, and the webhook answers with an error so the calling system knows to retry or alert someone.
const { config } = $('Workflow Configuration').first().json;
const err = ($input.first().json || {}).error;
const errText = typeof err === 'string' ? err : err && (err.message || err.description) ? String(err.message || err.description) : 'unknown error';
// The row that could not be saved (from whichever branch produced it).
const pick = (name) => { try { return $(name).isExecuted ? $(name).first().json : null; } catch (e) { return null; } };
const row = pick('Parse & Safety Check') || pick('Manual Review Fallback') || {};
const to = String(config.staff_notification.to || '').trim();
const fields = Object.entries(row).map(([k, v]) => `${k}: ${String(v).replace(/\n/g, ' | ')}`).join('\n');
return [{
  json: {
    notify: Boolean(to),
    lead_id: row.lead_id || '',
    error: String(errText).slice(0, 300),
    notification: {
      to,
      subject: `[ACTION NEEDED] Lead ${row.lead_id || ''} could NOT be saved to the lead register`.trim(),
      body: `The lead register (Google Sheets) could not be updated, so this lead exists only in this email and in n8n's execution log.\n` +
        `Please add it to the register manually and reply to the customer as usual. Nothing has been sent to the customer.\n\n` +
        `Error: ${String(errText).slice(0, 300)}\n\n${fields}`,
    },
  },
}];
